(do
  let source := SolidCore.Solidity.SolcAstImport.OpenZeppelinSignedMath.importedSourceUnit
  let program <- SolidCore.Solidity.TypeCheck.CheckedInput.program source
  let contract <- SolidCore.Solidity.TypeCheck.CheckedProgram.contract program "OpenZeppelinSignedMathHarness"
  let int := SolidCore.Solidity.Source.Value.int
  let word := SolidCore.Solidity.Source.Value.word
  let signed := SolidCore.Solidity.Shared.signedToWord
  let callInt := fun fuel name args expected => do
    let result <- SolidCore.Solidity.TypeCheck.CheckedContract.call fuel contract (SolidCore.Solidity.Source.CallTarget.name name) SolidCore.Solidity.Source.State.empty args
    match result with
    | SolidCore.Solidity.Source.CallResult.returned _ [SolidCore.Solidity.Source.Value.int value] =>
        Except.ok (SolidCore.Solidity.Source.wordEq value expected)
    | _ => Except.ok false
  let maxMixed <- callInt 64 "max" [int (signed (-4)), int (signed 7)] (signed 7)
  let maxNegative <- callInt 64 "max" [int (signed (-9)), int (signed (-3))] (signed (-3))
  let minMixed <- callInt 64 "min" [int (signed (-4)), int (signed 7)] (signed (-4))
  let minNegative <- callInt 64 "min" [int (signed (-9)), int (signed (-3))] (signed (-9))
  let ternaryTrue <- callInt 64 "ternary" [word 1, int (signed (-11)), int (signed 22)] (signed (-11))
  let ternaryFalse <- callInt 64 "ternary" [word 0, int (signed (-11)), int (signed 22)] (signed 22)
  Except.ok (maxMixed && maxNegative && minMixed && minNegative && ternaryTrue && ternaryFalse))

