(do
  let source := SolidCore.Solidity.SolcAstImport.AbiMalformed.importedSourceUnit
  let program <- SolidCore.Solidity.TypeCheck.CheckedInput.program source
  let contract <- SolidCore.Solidity.TypeCheck.CheckedProgram.contract program "AbiMalformed"
  let emptyRevert := fun result =>
    match result with
    | SolidCore.Solidity.Source.CallResult.reverted _ SolidCore.Solidity.Source.RevertData.empty => true
    | _ => false
  let check := fun functionName target signature output => do
    let calldata := SolidCore.Solidity.Source.ABI.encodeSelector (SolidCore.Solidity.Source.ABI.selectorFromSignature signature)
    let callResult : SolidCore.Solidity.Source.LowLevelCallResult :=
      { kind := SolidCore.Solidity.Source.LowLevelCallKind.call
        target := target
        calldata := calldata
        success := true
        output := output }
    let context :=
      { contract.core.context with
        accountCodes := [(target, [0x60, 0x00])] }
    let result <- SolidCore.Solidity.TypeCheck.CheckedContract.callFunctionWithContextUnderResponder 256 (SolidCore.Solidity.Source.responderOfResults [callResult] []) contract functionName context SolidCore.Solidity.Source.State.empty [SolidCore.Solidity.Source.Value.word target]
    Except.ok (emptyRevert result)
  let narrow <- check "highLevelNarrowReturn" 0xbeef "narrowValue()" (SolidCore.Solidity.Source.ABI.encodeWord 256)
  let enum <- check "highLevelEnumReturn" 0xee11 "enumValue()" (SolidCore.Solidity.Source.ABI.encodeWord 2)
  let address <- check "highLevelAddressReturn" 0xaadd "addressValue()" (SolidCore.Solidity.Source.ABI.encodeWord (2 ^ 160))
  let fixed <- check "highLevelFixedBytesReturn" 0xf1ed "fixedBytesValue()" ([1, 2, 3, 4] ++ List.replicate 27 0 ++ [1])
  let ignoredAddress <- check "highLevelIgnoredAddressReturn" 0x1a11 "pairValue()" (SolidCore.Solidity.Source.ABI.encodeWord 7 ++ SolidCore.Solidity.Source.ABI.encodeWord (2 ^ 160))
  let ignoredFixed <- check "highLevelIgnoredFixedBytesReturn" 0x1f1d "pairValue()" (SolidCore.Solidity.Source.ABI.encodeWord 7 ++ [1, 2, 3, 4] ++ List.replicate 27 0 ++ [1])
  Except.ok (narrow && enum && address && fixed && ignoredAddress && ignoredFixed))
